from typing import Any, List, Dict, Optional
import re

def run(left: List[Dict[str, Any]], right: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    # Validate left records
    left_fields = {"invoice_id", "po_number", "vendor", "amount", "invoice_date"}
    for i, rec in enumerate(left):
        for field in left_fields:
            if field not in rec:
                raise ValueError(field)

    # Validate right records
    right_fields = {"po_id", "po_number", "vendor", "amount", "po_date", "status"}
    for i, rec in enumerate(right):
        for field in right_fields:
            if field not in rec:
                raise ValueError(field)

    # Precompute normalized PO numbers for right records
    def digits_only(s: str) -> str:
        return re.sub(r'[^0-9]', '', s)

    right_norm_map: Dict[str, List[Dict[str, Any]]] = {}
    for r in right:
        k = digits_only(r["po_number"])
        if k not in right_norm_map:
            right_norm_map[k] = []
        right_norm_map[k].append(r)

    results = []
    for l in left:
        k = digits_only(l["po_number"])

        if not k or k not in right_norm_map:
            results.append({
                "left_id": l["invoice_id"],
                "right_id": None,
                "status": "po_not_found"
            })
            continue

        matches = right_norm_map[k]
        if len(matches) > 1:
            results.append({
                "left_id": l["invoice_id"],
                "right_id": None,
                "status": "manual_review"
            })
            continue

        r = matches[0]
        right_id = r["po_id"]

        # Check vendor (equals_ci)
        left_vendor = l["vendor"]
        right_vendor = r["vendor"]
        if not isinstance(left_vendor, str) or not isinstance(right_vendor, str):
            results.append({
                "left_id": l["invoice_id"],
                "right_id": right_id,
                "status": "vendor_mismatch"
            })
            continue
        if left_vendor.strip().lower() != right_vendor.strip().lower():
            results.append({
                "left_id": l["invoice_id"],
                "right_id": right_id,
                "status": "vendor_mismatch"
            })
            continue

        # Check amount (within_pct 0.5%)
        left_amount = l["amount"]
        right_amount = r["amount"]
        if not isinstance(left_amount, (int, float)) or not isinstance(right_amount, (int, float)):
            results.append({
                "left_id": l["invoice_id"],
                "right_id": right_id,
                "status": "amount_mismatch"
            })
            continue
        tolerance = 0.5 / 100 * abs(right_amount)
        if abs(left_amount - right_amount) > tolerance:
            results.append({
                "left_id": l["invoice_id"],
                "right_id": right_id,
                "status": "amount_mismatch"
            })
            continue

        # All checks passed
        results.append({
            "left_id": l["invoice_id"],
            "right_id": right_id,
            "status": "auto_match_and_enter"
        })

    return results
